import{z as B,x as A,o as r,c as p,q as l,j as i,D as e,d as t,s as n,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Percolator","description":"","frontmatter":{"title":"Percolator","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/percolator.md","filePath":"cs/percolator.md","lastUpdated":1791413859000}'),d={name:"cs/percolator.md"};function c(m,a,P,D,C,T){const E=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="percolator" tabindex="-1">Percolator <a class="header-anchor" href="#percolator" aria-label="Permalink to &quot;Percolator&quot;">​</a></h1><div class="epigraph"><p>在无跨行事务的 Bigtable 上，用锁列、写意图与一次提交时间戳，把多行更新收成客户端驱动的 2PC 变体。</p><footer>—— 据 Peng and Dabek, Large-scale Incremental Processing Using Distributed Transactions and Notifications, OSDI 2010</footer></div><p><a href="/cs/distributed-join-shuffle">上一课</a>搬运连接数据。本课不 shuffle。缺口是宽列存储默认单行原子：索引与网页库要跨行事务。Percolator 在单元格上加 lock/write/data 列，客户端做两阶段：预写抢锁写意图，提交打时间戳。增量处理（文档更新通知）叠在事务上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bigtable 行原子、跨行无。搜索索引更新要同时改多行。缺口是<strong>把 2PC 状态机编码进表</strong>，不用独立事务管理器进程（协调器是客户端+时间戳服务器）。时间戳服务器给单调戳，类似 TSO。锁超时与崩溃：扫 lock 列清理。</p><p><span class="marginnote">「2PC」（两阶段提交）就是把「先都准备好、再一起生效」拆成两步的协议。Percolator 的巧思在于协调状态不放在独立进程里，而是编码进每个单元格的 lock 列——客户端崩了，留下的只是一些待清理的锁，而不是一个卡死的协调器。</span></p><p>与 Calvin：Percolator 悲观锁+戳，非全局定序全部事务。与 Spanner：无 TrueTime 提交等待，SI 风格。</p><p><span class="marginnote">Peng and Dabek, OSDI 2010，Google。本课机制。后续 Cockroach 等受 TSO+锁启发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Get/Prepare/Commit 协议：读带快照戳；写先对行写 lock 与新 data；全部预写成功则提交戳写入 write 列，清 lock。冲突：发现 lock 则等或 abort。通知：提交后把脏键放入队列做增量作业。</p><p>隔离：快照读 + 写写冲突检测，近似 SI，写偏斜按产品是否额外检测。</p><p><span class="marginnote">数字实例——快照读怎么挑版本：设快照戳为 100，某单元格 write 列里登记了 80、95、102 三个版本，读者取不超过 100 的最大者 95 对应的 data。既看不到 102 的新值，也不会误读成比 80 更早的状态。</span></p>',12)),(r(),i(s,null,{default:e(()=>[n(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TS%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%20--%3E%20PW%5B%22%E9%A2%84%E5%86%99%3A%20lock%2Bdata%22%5D%0A%20%20PW%20--%3E%20CM%5B%22%E6%8F%90%E4%BA%A4%E6%88%B3%E5%86%99%E5%85%A5%20write%20%E5%88%97%22%5D%0A%20%20CM%20--%3E%20NTF%5B%22%E5%A2%9E%E9%87%8F%E9%80%9A%E7%9F%A5%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[t("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"性能：每行多列、多次 RPC，热点行锁。适合吞吐增量，不适合超短 OLTP 延迟。恢复：无独立 undo 日志，意图行即状态。WAL 在 Bigtable 层。",-1)),(r(),i(s,null,{default:e(()=>[n(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E8%AF%BB%E5%88%B0%E4%B8%80%E8%A1%8C%E5%B8%A6%E6%AE%8B%E7%95%99%20lock%22%5D%20--%3E%20PRI%5B%22%E6%89%BE%E5%88%B0%E8%AF%A5%E4%BA%8B%E5%8A%A1%E7%9A%84%E4%B8%BB%E9%94%81%E8%A1%8C%22%5D%0A%20%20PRI%20--%3E%20Q%7B%22%E4%B8%BB%E9%94%81%E8%A1%8C%E7%9A%84%20write%20%E5%88%97%E5%B7%B2%E6%9C%89%E6%8F%90%E4%BA%A4%E6%88%B3%3F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20FWD%5B%22%E6%9B%BF%E5%AE%83%E6%94%B6%E5%B0%BE%3A%20%E6%8A%8A%E6%84%8F%E5%9B%BE%E8%BD%AC%E6%AD%A3%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%E4%B8%94%E9%94%81%E5%B7%B2%E8%B6%85%E6%97%B6%7C%20ABT%5B%22%E5%9B%9E%E6%BB%9A%3A%20%E6%B8%85%E9%94%81%E5%88%A0%E6%84%8F%E5%9B%BE%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%E4%B8%94%E6%9C%AA%E8%B6%85%E6%97%B6%7C%20WAIT%5B%22%E5%86%8D%E7%AD%89%E7%AD%89%E6%8F%90%E4%BA%A4%E8%80%85%22%5D%0A%20%20FWD%20--%3E%20OK%5B%22%E8%AF%BB%E8%80%85%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20ABT%20--%3E%20OK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>与 CDC：通知队列是内部 CDC。逻辑复制课的下游思想在此是同一公司流水线。</p><p><span class="marginnote">常见误区：以为跨行事务必须有一个专职「事务协调器」服务在盯。这里协调器就是客户端本身，进度全写在表里；代价是每次提交要多次 RPC——取时间戳、逐行写锁、再清锁——这正是它不适合超低延迟 OLTP 的根源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 TrueTime。也不把 Percolator 当 SQL 优化器。分布式死锁后课：锁在表里，等待图跨客户端。</p><p>后课默认：可在 KV/宽列上叠客户端 2PC。Spanner 与 TrueTime：用时钟不确定区间给提交时间，实现外部一致。</p><p>把锁塞进数据表，协调器失败变成「行上残留 lock」的清理问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Percolator 用锁列与提交戳在 Bigtable 上做跨行事务。</li><li>时间戳服务器+客户端协议；适合增量，不适合超低延迟。</li><li>Spanner 与 TrueTime 下一课。</li><li>出处：Peng and Dabek, OSDI 2010。</li></ul>',8))])}const f=B(d,[["render",c]]);export{h as __pageData,f as default};
